    FN(cublasLtMatmulAlgoConfigGetAttribute) LtAlgoConfigGet;
    FN(cublasLtMatmulAlgoInit) LtAlgoInit;
    FN(cublasLtMatmulDescInit_internal) LtDescInit;
    FN(cublasLtMatmulDescCreate) LtDescCreate;
    FN(cublasLtMatmulDescDestroy) LtDescDestroy;
    FN(cublasLtMatmulDescGetAttribute) LtDescGet;
    FN(cublasLtMatmulDescSetAttribute) LtDescSet;
    FN(cublasLtMatrixLayoutInit_internal) LtLayoutInit;
    FN(cublasLtMatrixLayoutCreate) LtLayoutCreate;
    FN(cublasLtMatrixLayoutDestroy) LtLayoutDestroy;
